<h1><?= te('Qualifications & expiry') ?></h1><p class="sub"><?= te('Configure evidence requirements by project. Expired or unverified qualifications block deployment; this does not replace regulatory verification.') ?></p>
<?php if(!$own): ?><div class="grid g2"><div class="card"><h2><?= te('Project requirements') ?></h2><?php if(!$requirements): ?><p class="hint"><?= te('Nothing is required on this project yet, so no qualification blocks a deployment.') ?></p><?php endif; ?><?php foreach($requirements as $r): ?><p><?= e(trim($r['name'].' · '.$r['required_detail'], ' ·')) ?></p><?php endforeach; ?><form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="requirement"><label><?= te('Qualification') ?><select name="type_id"><?php foreach($types as $t): ?><option value="<?= (int)$t['id'] ?>"><?= e($t['name']) ?></option><?php endforeach; ?></select></label><label><?= te('Required class or endorsement') ?><input name="detail" maxlength="190"></label><label><?= te('Apply qualification requirements to this trade only') ?><input name="trade_scope" maxlength="190"></label><button class="btn"><?= te('Add requirement') ?></button></form></div><?php if(can('admin')): ?><div class="card"><h2><?= te('Qualification catalogue') ?></h2><form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="type"><label><?= te('Name') ?><input name="name" required maxlength="190"></label><label><input style="width:auto" type="checkbox" name="expires_required" checked> <?= te('Expiry required') ?></label><button class="btn"><?= te('Add') ?></button></form></div><?php endif; ?></div><div class="card"><h2><?= te('Expires within 30 days or already expired') ?></h2><?php if(!$expiring): ?><p class="hint"><?= te('Nothing expires in the next 30 days. Only verified qualifications are counted here.') ?></p><?php endif; ?><?php foreach($expiring as $r): ?><p><span class="tag <?= $r['expires_on'] < date('Y-m-d') ? 'red' : 'amber' ?>"><?= $r['expires_on'] < date('Y-m-d') ? te('Expired') : te('Expiring') ?></span> <a href="/qualifications?candidate_id=<?= (int)$r['candidate_id'] ?>"><?= e($r['full_name']) ?></a> &middot; <?= e($r['name']) ?> &middot; <?= e(d($r['expires_on'])) ?></p><?php endforeach; ?></div><form class="card" method="get"><label><?= te('Employee') ?><select name="candidate_id"><?php foreach($candidates as $c): ?><option value="<?= (int)$c['id'] ?>" <?= $cid===(int)$c['id']?'selected':'' ?>><?= e($c['full_name']) ?></option><?php endforeach; ?></select></label><button class="btn"><?= te('Open folder') ?></button></form><?php endif; ?>
<?php if($cid): ?><div class="card"><h2><?= te('Submit qualification evidence') ?></h2><p><?= te('Upload private evidence in Document proofs and reference its document ID here. Do not enter a full licence or identity number.') ?></p><form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="record"><input type="hidden" name="candidate_id" value="<?= $cid ?>"><div class="grid g2"><label><?= te('Qualification') ?><select name="type_id"><?php foreach($types as $t): ?><option value="<?= (int)$t['id'] ?>"><?= e($t['name']) ?></option><?php endforeach; ?></select></label><label><?= te('Class or endorsement') ?><input name="detail" maxlength="190"></label><label><?= te('Issued on') ?><input type="date" name="issued_on"></label><label><?= te('Expires on') ?><input type="date" name="expires_on"></label><label><?= te('Evidence reference') ?><input name="evidence_reference" required maxlength="190"></label></div><button class="btn"><?= te('Submit for review') ?></button></form></div>
<?php foreach($records as $r): ?><div class="card"><h2><?= e($r['name']) ?></h2><p><?= e($r['detail'].' · '.$r['expires_on']) ?> · <?= te($r['status']) ?></p><p><?= e($r['evidence_reference']) ?></p><?php if(!$own): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="review"><input type="hidden" name="candidate_id" value="<?= $cid ?>"><input type="hidden" name="qualification_id" value="<?= (int)$r['id'] ?>"><select name="status"><option value="verified"><?= te('Verified') ?></option><option value="rejected"><?= te('Rejected') ?></option></select><label><?= te('Review notes') ?><textarea name="note" required maxlength="2000"></textarea></label><button class="btn"><?= te('Review') ?></button></form><?php endif; ?></div><?php endforeach; ?><div class="card"><h2><?= te('History') ?></h2><?php foreach($events as $event): ?><p><?= e($event['created_at'].' · '.$event['name'].' · '.$event['action'].' · '.$event['note']) ?></p><?php endforeach; ?></div><?php endif; ?>
